from pathlib import Path

sources = json.loads(Path('source.json').read_text())
refs = json.loads(Path('reference-targets.json').read_text())
answers = []

def xml(*paragraphs):
    return '\n'.join('<p>' + html.escape(p, quote=False) + '</p>' for p in paragraphs)

def base(i):
    s = sources[i]
    a = {k: s[k] for k in ['code_id', 'source_id', 'source_sha256', 'number']}
    a.update(proposed_xml=s['previous_draft']['proposed_xml'],
             reason=s['previous_draft']['reason'],
             review_notes=s['previous_draft']['review_notes'], status='rewrite_draft')
    answers.append(a)
    return a

for i in range(12):
    base(i)

